/* Pseudo-SQL + pseudocode illustrating the pattern */

-- idempotency_table(key TEXT, endpoint TEXT, state TEXT, status INT, response JSONB, created_at TIMESTAMP, updated_at TIMESTAMP)
-- UNIQUE(key, endpoint)

BEGIN TRANSACTION;
-- try to insert a row marking the operation as in_progress
INSERT INTO idempotency_table(key, endpoint, state, created_at)
VALUES ($1, $2, 'in_progress', now())
ON CONFLICT DO NOTHING;

-- check if we inserted or row already existed
SELECT state, status, response FROM idempotency_table
WHERE key=$1 AND endpoint=$2 FOR UPDATE;

IF state = 'in_progress' THEN
  -- we are the worker responsible for executing operation
  result = call_payment_gateway(payload);
  UPDATE idempotency_table SET state='complete', status=result.status, response=result.body, updated_at=now()
  WHERE key=$1 AND endpoint=$2;
  COMMIT;
  RETURN result;
ELSE
  -- someone else already ran it; return stored response
  COMMIT;
  RETURN stored status/response;
END IF;

