/* Minimal append and projection (Node.js pseudo) */
async function appendEvent(eventStore, eventBus, aggregateId, event) {
  // atomic append
  await eventStore.append(aggregateId, event);
  // publish for eventual consumers
  await eventBus.publish(event);
}

// Rebuild aggregate by replaying events
function rebuildUserFrom(events) {
  const user = { id: null, email: null, version: 0 };
  for (const e of events) {
    if (e.type === 'UserCreated') {
      user.id = e.aggregateId;
    }
    if (e.type === 'UserEmailUpdated') {
      user.email = e.data.email;
    }
    user.version++;
  }
  return user;
}
